import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<String, Integer> memo = new HashMap<>();

    static int go(int n, int h) {
        String key = n + "," + h;
        if (!memo.containsKey(key)) {
            int result;
            if (n == 0) {
                result = 1;
            } else {
                int sum = 0;
                for (int i = 0; i < n; i++) {
                    sum += go(i, h - 1) * go(n - 1 - i, h - 1);
                }
                result = (h != 0 && sum != 0) ? sum : 0;
            }
            memo.put(key, result);
        }
        return memo.get(key);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int h = sc.nextInt();
        System.out.println(go(n, n) - go(n, Math.max(0, h - 1)));
        sc.close();
    }
}
